query:
SELECT 
  (SELECT COUNT(*) FROM variety_genealogy) as total_relations,
  (SELECT COUNT(*) FROM variety_genealogy vg
   WHERE NOT EXISTS (SELECT 1 FROM plant_varieties v WHERE v.id = vg.variety_id)
      OR NOT EXISTS (SELECT 1 FROM plant_varieties p WHERE p.id = vg.parent_variety_id)
  ) as orphelins_restants;

